        "description": "A user can only have one bill in the AWAITING PAYMENT status at a time.",
        "conditions": [
          {
            "type": "status_check",
            "field": "bill_status",
            "value": "AWAITING PAYMENT",
            "max_count": 1
          }
        ],
        "actions": [
          {
            "type": "deny_request",
            "message": "You already have a payment request pending. Please complete or cancel the existing request before creating a new one."
          }
        ]
      },
      {
        "id": "2",
        "name": "Overdue_Bill_Validation",
        "description": "Always check that the bill is overdue before sending a payment request.",
        "conditions": [
          {
            "type": "status_check",
            "field": "bill_status",
            "value": "OVERDUE"
          }
        ],
        "actions": [
          {
            "type": "tool_call",
            "tool": "send_payment_request",
            "input": {
              "bill_id": "{user_bill_id}"
            }
          },
          {
            "type": "user_message",
            "message": "A payment request has been sent for your overdue bill. Please check your payment requests using the provided tool."
          }
        ]
      },
      {
        "id": "3",
        "name": "Suspension_Lift_Contract_Check",
        "description": "Do not lift suspension if the line's contract end date is in the past.",
        "conditions": [
          {
            "type": "date_check",
            "field": "contract_end_date",
            "value": "past"
          }
        ],
        "actions": [
          {
            "type": "deny_request",
            "message": "The line cannot be reactivated because the contract has ended. Please contact a human agent for further assistance."
          }
        ]
      },
      {
        "id": "4",
        "name": "Bill_Payment_Confirmation",
        "description": "Always check that the bill status is updated to PAID before informing the user.",
        "conditions": [
          {
            "type": "status_check",
            "field": "bill_status",
            "value": "PAID"
          }
        ],
        "actions": [
          {
            "type": "user_message",
            "message": "Your bill has been successfully paid. Thank you."
          }
        ]
      },
